const data = $input.first().json;
const workflowName = data.workflow && data.workflow.name ? data.workflow.name : 'Unknown workflow';
const nodeName = data.error && data.error.node && data.error.node.name ? data.error.node.name : 'Unknown node';
const errorMsg = (data.error && data.error.message) ? data.error.message : 'Unknown error';
const chatId = $env.TELEGRAM_HUNTER_CHAT_ID;

const isCaptcha = errorMsg.toLowerCase().includes('captcha');
const isTimeout = errorMsg.toLowerCase().includes('timeout') || errorMsg.toLowerCase().includes('timed out');
const isBridgeDown = errorMsg.toLowerCase().includes('econnrefused') || errorMsg.toLowerCase().includes('hunter bridge') || errorMsg.toLowerCase().includes('18798');

let text;
if (isCaptcha) {
  text = '🔒 *CAPTCHA LinkedIn détecté !*\n\nLe scraper s\'est arrêté. Reconnectez la session LinkedIn manuellement puis relancez le scan.';
} else if (isBridgeDown) {
  text = '🔴 *Hunter Bridge inaccessible !*\n\n*Workflow :* ' + workflowName + '\n*Erreur :* ' + errorMsg.slice(0, 200);
} else if (isTimeout) {
  text = '⏱ *Timeout pipeline Job Hunter*\n\n*Workflow :* ' + workflowName + '\n*Nœud :* ' + nodeName + '\n*Erreur :* ' + errorMsg.slice(0, 200);
} else {
  text = '🚨 *Erreur pipeline Job Hunter*\n\n*Workflow :* ' + workflowName + '\n*Nœud :* ' + nodeName + '\n*Erreur :* ' + errorMsg.slice(0, 300);
}

return [{ json: { text, chat_id: chatId } }];
